module.exports = async ({ github, context, core }) => {
const fs = require("fs");
const owner = context.repo.owner;
const repo = context.repo.repo;
const marqueur = "<!-- ela-monitoring-production -->";
const titre = "[MONITORING] Le site en ligne ne répond plus correctement";
const etat = process.env.ETAT || "technique";
// Ne jamais toucher aux incidents si le contrôleur n'a pas établi de verdict.
if (!["ok", "panne"].includes(etat)) {
  core.setFailed("Échec technique du monitoring : état du site inconnu. Consulter l'étape en erreur. Aucun incident de production modifié.");
  return;
}
const adresse = process.env.ADRESSE || "https://elatransfer.com/";
if (adresse !== "https://elatransfer.com/" || context.ref !== "refs/heads/main") {
  if (etat === "panne") core.setFailed("Contrôle en échec hors monitoring officiel : voir le rapport. Aucun incident de production modifié.");
  else core.notice("Contrôle réussi hors monitoring officiel. Aucun incident de production modifié.");
  return;
}

let sortie = "";
try {
  sortie = fs.readFileSync(`${process.env.RUNNER_TEMP}/sortie.txt`, "utf8");
} catch { sortie = "(sortie du contrôleur indisponible)"; }

// Une seule Issue d'incident à la fois : on la retrouve par son
// marqueur, jamais par son titre — un titre se reformule.
const ouvertes = await github.paginate(github.rest.issues.listForRepo, {
  owner, repo, state: "open", labels: "", per_page: 100
});
const incident = ouvertes.find(i => !i.pull_request && i.body && i.body.includes(marqueur));

const lien = `${context.serverUrl}/${owner}/${repo}/actions/runs/${context.runId}`;

if (etat === "ok") {
  if (incident) {
    await github.rest.issues.createComment({
      owner, repo, issue_number: incident.number,
      body: [
        "## Retour à la normale",
        "",
        `Le contrôle de \`${adresse}\` est repassé au vert.`,
        "",
        `Passage : ${lien}`,
        "",
        "```",
        sortie.trim(),
        "```",
        "",
        "---",
        "_Generated by [Claude Code](https://claude.ai/code)_"
      ].join("\n")
    });
    await github.rest.issues.update({
      owner, repo, issue_number: incident.number,
      state: "closed", state_reason: "completed"
    });
    core.notice(`Incident #${incident.number} clos : le site répond de nouveau.`);
  } else {
    core.notice("Le site en ligne répond. Rien à signaler.");
  }
  return;
}

const corps = [
  marqueur,
  "## P0 — le site en ligne ne répond plus correctement",
  "",
  `Adresse contrôlée : ${adresse}`,
  `Détecté : ${new Date().toISOString()}`,
  `Déclencheur : \`${context.eventName}\``,
  `Passage : ${lien}`,
  "",
  "**Deux contrôles complets ont détecté des anomalies**, à une minute d'intervalle. Incident à investiguer : ces mesures ne prouvent pas à elles seules l'origine du problème.",
  "",
  "### Ce que le contrôleur a mesuré",
  "",
  "```",
  sortie.trim(),
  "```",
  "",
  "### Ce que ça veut dire",
  "",
  "- « sert une AUTRE page » → un réglage d'hébergeur, pas le code.",
  "- « fichier(s) du site manquent » → `construire.sh` ne publie pas ce fichier.",
  "- « on ne peut pas réserver » → la page est en ligne et ne sert à rien.",
  "- « n'a pas publié le dernier main » ou « /version.json » → l'hébergeur (Cloudflare) sert un ancien commit : sa construction a échoué ou vise une autre branche.",
  "- « contient … ancienne règle » → un texte de l'ancien paiement est servi en ligne.",
  "- « réservation de bout en bout » ou « le dépôt répond » → le moteur ou le serveur ne prend plus de demande : c'est l'incident le plus grave. La sonde n'enregistre jamais rien (référence SONDE-).",
  "- « le service worker servi » → les téléphones qui ont installé le site gardent l'ancienne version.",
  "",
  "Aucune correction automatique n'est appliquée. Cette Issue se ferme d'elle-même dès qu'un contrôle repasse au vert.",
  "",
  "---",
  "_Generated by [Claude Code](https://claude.ai/code)_"
].join("\n");

if (incident) {
  await github.rest.issues.update({
    owner, repo, issue_number: incident.number, body: corps
  });
  core.setFailed(`Panne toujours en cours — incident #${incident.number} mis à jour.`);
} else {
  /* Assignée au propriétaire du dépôt : une Issue du robot ne notifie
     que ceux qui y participent (audit du 9 octobre 2026). */
  const cree = await github.rest.issues.create({
    owner, repo, title: titre, body: corps, assignees: [owner]
  });
  core.setFailed(`Panne détectée — incident #${cree.data.number} ouvert.`);
}
};
